async function startTurn(){if(!session||session.done)return;stopAll();resetTurn();const turnToken=generation,turnClick=instructionEpoch;if(exerciseVoiceKey()){await speak(phraseInstructions(),exerciseVoiceKey());if(turnToken!==generation||turnClick!==instructionEpoch||view!=='studio'||session.done)return}await speak('Your turn. Play exercise '+(session.index+1)+' of five. Follow the highlighted notes across both bars.','your-turn');if(turnToken!==generation||turnClick!==instructionEpoch||view!=='studio'||session.done)return;const choice=$('inputMode').value;if(current.chords&&!arpeggio&&!polyphonic&&choice==='mic'){$('feedback').textContent='Choose Arpeggios for microphone pitch matching, or strum the chord shapes and use self-review.';mode='review';return}if(choice==='review'){mode='review';startLessonPulse(false);$('feedback').textContent='Play both bars on your instrument, then select self-review.';return}if(choice==='midi'&&!midiAccess){$('feedback').textContent='Connect a MIDI instrument under input options, or select another input.';return}if(choice==='mic'){await startMic('practice');return}mode='practice';if($('timingMode').checked)startAt=performance.now()+4*beatMs;startLessonPulse(false);if($('timingMode').checked){startAt=performance.now()+4*beatMs;$('feedback').textContent='Count in: 1, 2, 3, 4. Begin after the clicks.';for(let i=0;i<4;i++)setTimer(()=>{click(audioContext(),audioContext().currentTime,i===0);$('feedback').textContent='Count-in '+(i+1)+' / 4'},i*beatMs);setTimer(()=>{processRest();$('feedback').textContent='Follow the highlighted notes.'},4*beatMs)}else{$('feedback').textContent='Play the highlighted notes. Keep counting through rests.';processRest()}}
