function acceptNote(n,input){if(!['practice','mic'].includes(mode)||!events[cursor])return;if(mode==='mic'&&input!=='mic')return;const e=events[cursor],wanted=notesOf(e);stopVoice();$('detected').textContent='Heard: '+pitchName(n);if(performance.now()<startAt){$('feedback').textContent='Wait until the count-in ends.';return}if(!wanted.length){wrong++;paintNote(n,false);$('feedback').className='error';$('feedback').textContent='Heard '+pitchName(n)+' during a rest. Keep counting in silence.';return}const good=wanted.includes(n);paintNote(n,good);$('detected').className='pill '+(good?'success':'error');if(!good){wrong++;$('feedback').className='error';$('feedback').textContent='Heard '+pitchName(n)+'. Expected '+eventLabel(e)+'. Try again.';return}const now=performance.now();if(now-lastChord>300)chordSet.clear();lastChord=now;chordSet.add(n);const unique=[...new Set(wanted)];if(!unique.every(n=>chordSet.has(n)))return;chordSet.clear();matched++;if($('timingMode').checked&&mode!=='mic'){const offset=events.slice(0,cursor).reduce((s,e)=>s+e.beats,0);onsets.push(now-startAt-offset*beatMs)}cursor++;$('feedback').className='success';$('feedback').textContent='✓ '+eventLabel(e)+' matched.';renderPhrase();processRest()}
